import sys

def solve(n, vals, edges, queries):
    from collections import defaultdict
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    tin, tout = [0] * (n + 1), [0] * (n + 1)
    timer = 0
    adj_ptr = [0] * (n + 1)
    path = [1]
    parent = [0] * (n + 1)
    timer += 1
    tin[1] = timer

    while path:
        u = path[-1]
        if adj_ptr[u] < len(adj[u]):
            v = adj[u][adj_ptr[u]]
            adj_ptr[u] += 1
            if v != parent[u]:
                parent[v] = u
                timer += 1
                tin[v] = timer
                path.append(v)
        else:
            tout[u] = timer
            path.pop()

    bit1 = [0] * (n + 2)
    bit2 = [0] * (n + 2)

    def bit_update(bit, idx, val):
        while idx <= n:
            bit[idx] += val
            idx += idx & (-idx)

    def bit_query(bit, idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & (-idx)
        return s

    def range_update(l, r, val):
        bit_update(bit1, l, val)
        bit_update(bit1, r + 1, -val)
        bit_update(bit2, l, val * (l - 1))
        bit_update(bit2, r + 1, -val * r)

    def prefix_sum(idx):
        return bit_query(bit1, idx) * idx - bit_query(bit2, idx)

    def range_sum(l, r):
        return prefix_sum(r) - prefix_sum(l - 1)

    for i in range(1, n + 1):
        range_update(tin[i], tin[i], vals[i-1])

    results = []
    for q in queries:
        if q[0] == 1:
            u, x = q[1], q[2]
            range_update(tin[u], tout[u], x)
        else:
            u = q[1]
            results.append(str(range_sum(tin[u], tout[u])))
    return "\n".join(results)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data: exit()
    idx = 0
    n = int(data[idx]); idx += 1
    vals = [int(data[idx+i]) for i in range(n)]; idx += n
    edges = []
    for _ in range(n-1): edges.append((int(data[idx]), int(data[idx+1]))); idx += 2
    q_count = int(data[idx]); idx += 1
    queries = []
    for _ in range(q_count):
        t = int(data[idx]); u = int(data[idx+1]); idx += 2
        v = 0
        if t == 1: v = int(data[idx]); idx += 1
        queries.append((t, u, v))
    print(solve(n, vals, edges, queries))

